#!/usr/bin/env bash
# unityHPC/run.sh — generated by /unity-hpc:setup. Do not hand-edit; re-run setup
# to regenerate. Any previous version is preserved under unityHPC/.pre-redesign/.
#
# Usage:
#   run.sh run <exp> [--campaign N] [--dry-run] [sbatch args...]  submit one job
#   run.sh array <manifest> [--campaign N] [--limit N] [sbatch args...] submit an array
#   run.sh render <exp>                    print the sbatch script, submit nothing
#   run.sh sync                            rsync the project to $REMOTE_DIR
#   run.sh status [--campaign N]           live sacct check; updates the ledger
#   run.sh jobs [--campaign N]             print the ledger (local, no SSH)
#   run.sh logs [--campaign N] [-n LINES]  tail the newest job's stdout and stderr
#   run.sh fetch [--campaign N]            rsync this campaign's output locally
#
# Any of JOB_COMMAND, WALLTIME, SLURM_{PARTITION,CPUS,MEM,NODES,GPUS,GPU_TYPE,
# ACCOUNT,PARTITION_FALLBACK,PARTITION_WALLTIME_CAP}, REMOTE_DIR, UNITY_HOST and
# CAMPAIGN may be overridden for a single invocation without touching .env:
#   JOB_COMMAND="echo smoke-test" SLURM_MEM=1G bash run.sh run smoke
# PROJECT_NAME, MODEL, DATASET, SEED and CONFIG_HASH are optional provenance.
# UNITY_SSH_TIMEOUT sets the maximum wait for one SSH call, in seconds.
# SLURM_PARTITION_FALLBACK="cpu cpu-preempt ood-shared" retries a rejected
# sbatch on later partitions (unset = today's single attempt; an explicit
# caller SLURM_PARTITION disables this). SLURM_PARTITION_WALLTIME_CAP=
# "ood-shared=08:00:00" clamps WALLTIME per partition before each retry.
#
# Every submitted job is recorded in ../.unity_state/<campaign>.db, which is what
# /unity-hpc:status, unity_jobs and unity_my_jobs read. The ledger writer is
# inlined below on purpose: this script must keep working after a plugin upgrade
# moves the plugin's own files, so it never imports from the plugin directory.
set -euo pipefail

# The plugin version that generated this file. This script is a COPY living in
# the project, so upgrading the plugin does not upgrade it -- that is the price
# of it being self-contained enough to survive the plugin moving. The stamp is
# what makes the resulting drift visible: unity_doctor compares it against the
# running plugin and tells you to re-run /unity-hpc:setup. Without it, a project
# silently keeps an old dispatcher and features documented elsewhere are simply
# absent.
UNITY_SCAFFOLD_VERSION="@@UNITY_HPC_VERSION@@"

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJECT_DIR="$(cd "$HERE/.." && pwd)"
STATE_DIR="$PROJECT_DIR/.unity_state"

if [ -f "$HERE/.env" ]; then
    ENV_FILE="$HERE/.env"
elif [ -f "$PROJECT_DIR/.env" ]; then
    ENV_FILE="$PROJECT_DIR/.env"
else
    echo "run.sh: no .env found (looked in $HERE/.env and $PROJECT_DIR/.env)" >&2
    exit 2
fi
# The caller's environment wins over .env for these. Sourcing alone would
# overwrite them, which meant the only way to run one small job -- a smoke test,
# a resized retry -- was to edit the file every other run depends on. A
# non-empty value passed in for one invocation is always deliberate.
# Everything render() bakes into the job script belongs here. MODULES,
# VENV_PATH and HF_HOME were missing, so they could not be set for one run the
# way their siblings could -- and a caller passing MODULES=gcc silently got
# .env's empty value instead, which looks exactly like a broken module system.
UNITY_OVERRIDABLE="JOB_COMMAND WALLTIME SLURM_PARTITION SLURM_CPUS SLURM_MEM
                   SLURM_NODES SLURM_GPUS SLURM_GPU_TYPE SLURM_CONSTRAINT SLURM_ACCOUNT
                   SLURM_PARTITION_FALLBACK SLURM_PARTITION_WALLTIME_CAP
                   REMOTE_DIR UNITY_HOST CAMPAIGN
                   MODULES VENV_PATH HF_HOME USER_EMAIL
                   UNITY_CID PROJECT_NAME MODEL DATASET SEED CONFIG_HASH"
# `${!var+x}` tests whether the variable is SET, not whether it is non-empty.
# That distinction matters: `SLURM_GPUS= run.sh run x` is how you turn a GPU
# request off for one invocation, and treating empty as "not supplied" made that
# impossible -- a project whose .env requests a GPU could not be smoke-tested on
# cpu at all. Setting a variable to empty is something you can only do on
# purpose. Blanking is safe here because the defaults below re-fill anything
# optional, and the required values fail loudly rather than silently.
for _var in $UNITY_OVERRIDABLE; do
    if [ -n "${!_var+x}" ]; then
        eval "_unity_caller_set_${_var}=1"
        eval "_unity_caller_${_var}=\${${_var}}"
    fi
done

set -a; . "$ENV_FILE"; set +a

for _var in $UNITY_OVERRIDABLE; do
    _flag="_unity_caller_set_${_var}"
    if [ -n "${!_flag+x}" ]; then
        eval "${_var}=\${_unity_caller_${_var}}"
    fi
done
unset _var _flag

: "${UNITY_HOST:=unity}"
: "${WALLTIME:=04:00:00}"
: "${SLURM_CPUS:=8}"
: "${SLURM_MEM:=16G}"
: "${SLURM_PARTITION:=cpu}"
: "${SLURM_NODES:=1}"
: "${SLURM_GPUS:=}"
: "${SLURM_GPU_TYPE:=}"
: "${SLURM_CONSTRAINT:=}"
: "${SLURM_PARTITION_FALLBACK:=}"
: "${SLURM_PARTITION_WALLTIME_CAP:=}"
: "${CAMPAIGN:=}"
: "${UNITY_CID:=/work/${SLURM_ACCOUNT:-unknown-account}/${USER:-unknown-user}/cluster-intel}"
: "${PROJECT_NAME:=$(basename "$PROJECT_DIR")}"
: "${MODEL:=}"
: "${DATASET:=}"
: "${SEED:=}"
: "${CONFIG_HASH:=}"
: "${GIT_REVISION:=$(git -C "$PROJECT_DIR" rev-parse HEAD 2>/dev/null || true)}"
: "${UNITY_SSH_TIMEOUT:=60}"

require() {
    local name="$1"
    if [ -z "${!name:-}" ]; then
        echo "run.sh: $name must be set in $ENV_FILE" >&2
        exit 2
    fi
}

_write_provenance() {
    local job_id="$1" exp="$2" campaign="$3" tmp target qmanifest qtarget
    tmp="$(mktemp)"
    python3 - "$tmp" "$job_id" "$exp" "$campaign" "$PROJECT_NAME" \
        "$GIT_REVISION" "$MODEL" "$DATASET" "$SEED" "$CONFIG_HASH" <<'PY'
import json
import sys

path, job_id, exp, campaign, project, revision, model, dataset, seed, config_hash = sys.argv[1:]
record = {
    "job_id": job_id,
    "experiment": exp,
    "campaign": campaign,
    "project": project,
    "git_revision": revision,
    "model": model,
    "dataset": dataset,
    "seed": seed,
    "config_hash": config_hash,
}
with open(path, "w", encoding="utf-8") as fh:
    json.dump(record, fh, sort_keys=True)
    fh.write("\n")
PY
    target="${UNITY_CID}/manifests/${job_id}.json"
    printf -v qmanifest '%q' "${UNITY_CID}/manifests"
    printf -v qtarget '%q' "$target"
    timeout --foreground "$UNITY_SSH_TIMEOUT" ssh "$UNITY_HOST" \
        "mkdir -p -- ${qmanifest}"
    timeout --foreground "$UNITY_SSH_TIMEOUT" ssh "$UNITY_HOST" \
        "cat > ${qtarget}" <"$tmp"
    rm -f "$tmp"
}

_ssh() {
    timeout --foreground "$UNITY_SSH_TIMEOUT" ssh "$@"
}

# An experiment or campaign name becomes a SLURM job name, a local filename, a
# remote filename AND part of a remote shell command. A space silently corrupts
# the #SBATCH header and the output paths; a ';' or backtick would run on the
# shared login node. Reject anything that is not plainly a name.
_require_safe_name() {
    local what="$1" value="$2"
    case "$value" in
        "")
            echo "run.sh: $what must not be empty" >&2; exit 2 ;;
        *[!A-Za-z0-9._-]*)
            echo "run.sh: invalid $what: '$value'" >&2
            echo "run.sh:   use only letters, digits, '.', '_' or '-'. This name becomes" >&2
            echo "run.sh:   a job name, a filename and part of a remote command." >&2
            exit 2 ;;
        -*|.*)
            echo "run.sh: $what must not start with '-' or '.': '$value'" >&2; exit 2 ;;
    esac
    if [ "${#value}" -gt 64 ]; then
        echo "run.sh: $what is too long (max 64 characters): '$value'" >&2; exit 2
    fi
}

_require_safe_constraint() {
    case "$1" in
        *[!A-Za-z0-9_.\&\|\(\)-]*)
            echo "run.sh: invalid SLURM_CONSTRAINT: '$1'" >&2
            echo "run.sh: use only resource names plus '.', '_', '-', '&', '|', '(' and ')'" >&2
            exit 2 ;;
    esac
}

# sbatch/SLURM accept three walltime spellings: HH:MM:SS, D-HH:MM:SS and
# MM:SS. Converting to seconds is what lets a cap and a request from different
# spellings be compared.
_walltime_seconds() {
    local value="$1" days=0 rest="$1" h m s
    if [[ "$value" == *-* ]]; then
        days="${value%%-*}"
        rest="${value#*-}"
    fi
    IFS=: read -r h m s <<<"$rest"
    if [ -z "${s:-}" ]; then
        s="$m"; m="$h"; h=0
    fi
    # 10# on every field, days included: bash reads a leading-zero number as
    # octal, so a plain `08-00:00:00` would abort the script with "value too
    # great for base" rather than clamp anything.
    echo $(( 10#$days * 86400 + 10#$h * 3600 + 10#$m * 60 + 10#$s ))
}

# The smaller of REQUESTED and CAP, spelled the way its own argument was
# spelled -- sbatch accepts any of the three formats, so there is no need to
# reformat, and reformatting would make a test's expected value harder to
# read than the input it came from. An empty CAP means the partition has none.
_capped_walltime() {
    local requested="$1" cap="$2"
    if [ -z "$cap" ]; then
        printf '%s\n' "$requested"
        return 0
    fi
    if [ "$(_walltime_seconds "$requested")" -gt "$(_walltime_seconds "$cap")" ]; then
        printf '%s\n' "$cap"
    else
        printf '%s\n' "$requested"
    fi
}

# Surrounding whitespace stripped. An all-whitespace argument becomes empty.
_trim() {
    local s="$1"
    s="${s#"${s%%[![:space:]]*}"}"
    printf '%s\n' "${s%"${s##*[![:space:]]}"}"
}

# The three spellings _walltime_seconds can convert, and nothing else. A cap
# it cannot read is a typo, not a ceiling, and must never reach the arithmetic.
_is_walltime() {
    [[ "$1" =~ ^([0-9]+-)?[0-9]+:[0-9]+(:[0-9]+)?$ ]]
}

# SLURM_PARTITION_WALLTIME_CAP is "partition=HH:MM:SS,partition=HH:MM:SS,...".
# Echoes the cap for PARTITION, or nothing if it has none.
#
# Every rejected entry is named on stderr. A cap table is hand-written, and its
# two failure modes are both silent: "a=1:0:0, b=2:0:0" is the natural way to
# write a list but splitting on the comma alone yields the name " b", which
# matches no partition ever; and an entry with no "=" sets name == cap, so a
# partition NAME went into _walltime_seconds' arithmetic. Either way the cap
# the author wrote down simply did not apply, and the retry it was meant to
# rescue failed on walltime for no visible reason.
_walltime_cap_for() {
    local partition="$1" entry name cap
    local IFS=,
    for entry in ${SLURM_PARTITION_WALLTIME_CAP:-}; do
        entry="$(_trim "$entry")"
        [ -n "$entry" ] || continue
        name="$(_trim "${entry%%=*}")"
        cap="$(_trim "${entry#*=}")"
        if [ "$name" = "$entry" ]; then
            echo "run.sh: WARNING ignoring SLURM_PARTITION_WALLTIME_CAP entry" >&2
            echo "run.sh:   '${entry}': expected partition=HH:MM:SS" >&2
            continue
        fi
        if [ "$name" = "$partition" ]; then
            if ! _is_walltime "$cap"; then
                echo "run.sh: WARNING ignoring SLURM_PARTITION_WALLTIME_CAP entry" >&2
                echo "run.sh:   '${entry}': '${cap}' is not HH:MM:SS, D-HH:MM:SS or MM:SS" >&2
                return 0
            fi
            printf '%s\n' "$cap"
            return 0
        fi
    done
}

# An explicit caller SLURM_PARTITION means the caller named a partition on
# purpose, so it is honored alone -- the ladder does not second-guess it.
# Absent that, the ladder is only active when SLURM_PARTITION_FALLBACK is
# set: unset, cmd_run/cmd_array must keep today's single-attempt behavior
# exactly, with no synthetic --partition/--time added to the sbatch call.
#
# It is the caller's VALUE that stands the ladder down, not the mere fact that
# the caller mentioned the variable. `SLURM_GPUS= run.sh run x` is this
# script's documented way to turn an option off for one invocation, so
# `SLURM_PARTITION=` reads as "I am not naming a partition" -- the opposite of
# naming one, and no reason to disable a fallback list the .env asked for.
_ladder_is_active() {
    [ -n "$SLURM_PARTITION_FALLBACK" ] && [ -z "${_unity_caller_SLURM_PARTITION:-}" ]
}

# The ordered submit plan: one rung per line, "PARTITION<TAB>WALLTIME", the
# walltime already clamped by this partition's cap. An EMPTY walltime means the
# ladder is standing down, and the attempt must add no --partition/--time of
# its own -- byte-for-byte the single submit that preceded the ladder.
#
# Both _submit_ladder and cmd_run's --dry-run read this one function, which is
# what stops a preview from describing a submission that will not happen.
_submit_plan() {
    if ! _ladder_is_active; then
        printf '%s\t\n' "$SLURM_PARTITION"
        return 0
    fi
    local p
    for p in $SLURM_PARTITION_FALLBACK; do
        printf '%s\t%s\n' "$p" "$(_capped_walltime "$WALLTIME" "$(_walltime_cap_for "$p")")"
    done
}

# The sbatch arguments one rung of the plan contributes, and the one place that
# says out loud that a cap shortened the request: a job that silently runs for
# a third of the time asked for is a surprise worth a line. It is called at
# attempt time, so a rung the ladder never reaches never announces itself. The
# notice goes to stderr because this function's stdout IS the argument string.
_rung_args() {
    local p="$1" wt="$2"
    [ -n "$wt" ] || return 0
    if [ "$wt" != "$WALLTIME" ]; then
        echo "run.sh: partition ${p} capped this request at ${wt} (asked for ${WALLTIME})" >&2
    fi
    printf -- '--partition=%s --time=%s' "$p" "$wt"
}

# Result channel for _submit_ladder, read by the caller immediately after it
# returns -- the same pattern REST[] uses above for _take_campaign.
SUBMIT_JOB_ID=""
SUBMIT_PARTITION=""

# Submits REMOTE_SCRIPT (a path relative to REMOTE_DIR, already uploaded) via
# sbatch, walking _submit_plan until an attempt returns a job id or the
# ladder is exhausted. Each attempt's sbatch reply is printed as it happens,
# exactly as a single attempt always was. On success sets SUBMIT_JOB_ID and
# SUBMIT_PARTITION (the partition that attempt actually used) and returns 0;
# on failure leaves them empty, warns, and returns 1.
#
# Only a REFUSED submission (non-zero sbatch) advances the ladder. An accepted
# submission whose reply carries no job id stops it: that job is already
# queued, so a retry would run it twice. Every sbatch status is captured
# rather than left to `set -e`, so this is safe to call bare -- it does not
# depend on its callers wrapping it in `if !`.
_submit_ladder() {
    local remote_script="$1"; shift
    local sbatch_args=(${@+"$@"})
    SUBMIT_JOB_ID=""
    SUBMIT_PARTITION=""
    local p wt extra out job_id tried=()
    while IFS=$'\t' read -r p wt; do
        tried+=("$p")
        extra="$(_rung_args "$p" "$wt")"
        # `|| rc=$?`, not a bare assignment: sbatch exits non-zero on a
        # rejection, and under `set -e` a bare assignment would abort the
        # script there instead of letting the ladder do its job. Capturing the
        # status is also what separates the two failures below.
        local rc=0
        out="$(_ssh "$UNITY_HOST" "cd ${REMOTE_DIR} && sbatch ${extra} ${sbatch_args[*]-} ${remote_script}")" || rc=$?
        printf '%s\n' "$out"
        job_id="$(printf '%s\n' "$out" | sed -n 's/^Submitted batch job \([0-9][0-9]*\).*/\1/p' | head -1)"
        if [ -n "$job_id" ]; then
            SUBMIT_JOB_ID="$job_id"
            SUBMIT_PARTITION="$p"
            return 0
        fi
        # No job id, but sbatch ACCEPTED the submission: the job is queued and
        # we simply cannot name it. Moving to the next partition would queue a
        # second copy of the same job, and with no job id there is no ledger
        # row to scancel either copy by. Only a refusal is safe to retry.
        if [ "$rc" -eq 0 ]; then
            echo "run.sh: WARNING sbatch accepted this job on partition ${p} but its" >&2
            echo "run.sh:   reply carried no job id, so it was NOT recorded. The job is" >&2
            echo "run.sh:   queued: check squeue before resubmitting, or it runs twice." >&2
            return 1
        fi
    done < <(_submit_plan)
    echo "run.sh: WARNING could not read a job id from sbatch's reply --" >&2
    if [ "${#tried[@]}" -gt 1 ]; then
        echo "run.sh:   tried partition(s): ${tried[*]}" >&2
    fi
    return 1
}

# ─── job ledger ──────────────────────────────────────────────────────────────
# Kept in sync with the plugin's lib/campaign.py by tests/test_ledger_contract.py.
# Data is passed on argv, never on stdin: stdin belongs to the heredoc.

_ledger() {
    python3 - "$STATE_DIR" "$@" <<'PYEOF'
import os, sqlite3, sys
from datetime import datetime, timezone

SCHEMA = """CREATE TABLE IF NOT EXISTS jobs (
    job_id        TEXT PRIMARY KEY,
    exp           TEXT NOT NULL DEFAULT '',
    partition     TEXT NOT NULL DEFAULT '',
    status        TEXT NOT NULL DEFAULT 'PENDING',
    attempt       INTEGER NOT NULL DEFAULT 1,
    submitted_utc TEXT NOT NULL DEFAULT '',
    hardware      TEXT,
    elapsed_s     REAL,
    updated_utc   TEXT
)"""

TERMINAL = {"COMPLETED", "FAILED", "CANCELLED", "TIMEOUT", "OUT_OF_MEMORY",
            "NODE_FAIL", "BOOT_FAIL", "DEADLINE", "REVOKED", "PREEMPTED"}

# Ledgers written by an older plugin version lack these; add them in place.
COLUMNS = {"exp": "TEXT NOT NULL DEFAULT ''",
           "partition": "TEXT NOT NULL DEFAULT ''",
           "status": "TEXT NOT NULL DEFAULT 'PENDING'",
           "attempt": "INTEGER NOT NULL DEFAULT 1",
           "submitted_utc": "TEXT NOT NULL DEFAULT ''",
           "hardware": "TEXT", "elapsed_s": "REAL", "updated_utc": "TEXT"}

state_dir, mode, campaign = sys.argv[1], sys.argv[2], sys.argv[3]
path = os.path.join(state_dir, campaign + ".db")
now = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")

if mode in ("record", "array"):
    os.makedirs(state_dir, exist_ok=True)
elif not os.path.exists(path):
    sys.exit(0)

con = sqlite3.connect(path, timeout=10)
con.row_factory = sqlite3.Row
con.execute(SCHEMA)
have = {r[1] for r in con.execute("PRAGMA table_info(jobs)")}
for col, decl in COLUMNS.items():
    if col not in have:
        try:
            con.execute("ALTER TABLE jobs ADD COLUMN %s %s" % (col, decl))
        except sqlite3.Error:
            pass

if mode == "record":
    job_id, exp, partition = sys.argv[4], sys.argv[5], sys.argv[6]
    with con:
        con.execute(
            "INSERT INTO jobs (job_id, exp, partition, status, attempt, "
            "submitted_utc, updated_utc) VALUES (?,?,?,'PENDING',1,?,?) "
            "ON CONFLICT(job_id) DO UPDATE SET exp=excluded.exp, "
            "partition=excluded.partition",
            (job_id, exp, partition, now, now))
elif mode == "array":
    parent, partition, manifest = sys.argv[4], sys.argv[5], sys.argv[6]
    try:
        with open(manifest, encoding="utf-8") as fh:
            exps = [line.strip() for line in fh if line.strip()]
    except OSError:
        sys.exit(2)
    with con:
        for index, exp in enumerate(exps):
            job_id = f"{parent}_{index}"
            con.execute(
                "INSERT INTO jobs (job_id, exp, partition, status, attempt, "
                "submitted_utc, updated_utc) VALUES (?,?,?,'PENDING',1,?,?) "
                "ON CONFLICT(job_id) DO UPDATE SET exp=excluded.exp, "
                "partition=excluded.partition",
                (job_id, exp, partition, now, now))
elif mode == "rows":
    for r in con.execute("SELECT job_id, exp, partition, status FROM jobs ORDER BY rowid"):
        print("\t".join(str(x) for x in r))
elif mode == "ids":
    print(",".join(r[0] for r in con.execute(
        "SELECT DISTINCT CASE WHEN instr(job_id, '_') > 0 "
        "THEN substr(job_id, 1, instr(job_id, '_') - 1) ELSE job_id END "
        "FROM jobs ORDER BY rowid")))
elif mode == "newest":
    for r in con.execute("SELECT job_id, exp FROM jobs ORDER BY rowid DESC LIMIT 1"):
        print("\t".join(str(x) for x in r))
elif mode == "update":
    current = {r["job_id"]: r["status"] for r in con.execute("SELECT job_id, status FROM jobs")}
    changed = 0
    with con:
        for line in sys.argv[4].splitlines():
            parts = line.strip().split("|")
            if len(parts) < 2 or not parts[0]:
                continue
            jid = parts[0].split(".")[0]
            if jid not in current or current[jid] in TERMINAL:
                continue
            state = parts[1].strip()
            if state.startswith("CANCELLED by"):
                state = "CANCELLED"
            if not state or state == current[jid]:
                continue
            hardware = parts[2].strip() if len(parts) > 2 and parts[2].strip() else None
            con.execute("UPDATE jobs SET status=?, hardware=COALESCE(?, hardware), "
                        "updated_utc=? WHERE job_id=?", (state, hardware, now, jid))
            changed += 1
    print(changed)
con.close()
PYEOF
}

_campaign() {
    if [ -n "$CAMPAIGN" ]; then
        _require_safe_name "campaign name" "$CAMPAIGN"
        printf '%s\n' "$CAMPAIGN"
    else
        date -u +%Y%m%d
    fi
}

# Pull `--campaign NAME` out of an argument list, leaving the rest in REST[].
REST=()
_take_campaign() {
    REST=()
    while [ $# -gt 0 ]; do
        case "$1" in
            --campaign) CAMPAIGN="${2:-}"; shift 2 ;;
            --campaign=*) CAMPAIGN="${1#--campaign=}"; shift ;;
            *) REST+=("$1"); shift ;;
        esac
    done
}

# A rendered script that does not parse is a guaranteed failure that the
# scheduler accepts without complaint: sbatch replies with a job id, the ledger
# records a healthy submission, and every task dies on its first line. One
# release shipped an array script in exactly that state, and the only visible
# symptom was a 100% failure rate that no plugin tool could explain. Parse the
# script here, before it reaches the cluster.
#
# The local bash and the cluster's bash can differ. Set UNITY_SKIP_SYNTAX_CHECK=1
# to submit a script that this check rejects.
_check_syntax() {
    local label="$1" script="$2" errors
    if [ -n "${UNITY_SKIP_SYNTAX_CHECK:-}" ]; then
        return 0
    fi
    if errors="$(printf '%s\n' "$script" | bash -n 2>&1)"; then
        return 0
    fi
    echo "run.sh: the rendered ${label} is not valid bash. Nothing was submitted." >&2
    printf '%s\n' "$errors" | sed 's/^/run.sh:   /' >&2
    echo "run.sh:   Set UNITY_SKIP_SYNTAX_CHECK=1 to submit it anyway." >&2
    exit 2
}

render() {
    local exp="$1"
    _require_safe_name "experiment name" "$exp"
    require SLURM_ACCOUNT
    require REMOTE_DIR
    require JOB_COMMAND
    [ -z "$SLURM_CONSTRAINT" ] || _require_safe_constraint "$SLURM_CONSTRAINT"

    echo "#!/bin/bash"
    echo "#SBATCH --job-name=${exp}"
    echo "#SBATCH --account=${SLURM_ACCOUNT}"
    echo "#SBATCH --partition=${SLURM_PARTITION}"
    echo "#SBATCH --time=${WALLTIME}"
    echo "#SBATCH --nodes=${SLURM_NODES}"
    echo "#SBATCH --cpus-per-task=${SLURM_CPUS}"
    echo "#SBATCH --mem=${SLURM_MEM}"
    echo "#SBATCH --output=${REMOTE_DIR}/_slurm/${exp}-%j.out"
    echo "#SBATCH --error=${REMOTE_DIR}/_slurm/${exp}-%j.err"
    # "0" means no GPU, not a request for zero of them: a project that pins
    # SLURM_GPUS="0" in .env otherwise emits `--gres=gpu:0`, which is malformed.
    if [ -n "$SLURM_GPUS" ] && [ "$SLURM_GPUS" != "0" ]; then
        if [ -n "$SLURM_GPU_TYPE" ]; then
            echo "#SBATCH --gres=gpu:${SLURM_GPU_TYPE}:${SLURM_GPUS}"
        else
            echo "#SBATCH --gres=gpu:${SLURM_GPUS}"
        fi
    fi
    if [ -n "$SLURM_CONSTRAINT" ]; then
        echo "#SBATCH --constraint=${SLURM_CONSTRAINT}"
    fi
    echo "#SBATCH --mail-type=END,FAIL,TIME_LIMIT"
    if [ -n "${USER_EMAIL:-}" ]; then
        echo "#SBATCH --mail-user=${USER_EMAIL}"
    fi
    echo ""
    # %q, not "$var": a JOB_COMMAND containing a double quote -- `python train.py
    # --name "my run"` -- otherwise closes the assignment early, so the tail of
    # the command runs as separate shell commands at export time while the job
    # still reports success. %q emits a form bash re-reads exactly. Expansion of
    # $EXP, $SLURM_JOB_ID and friends still happens, just at `eval` time.
    printf 'export EXP=%q\n' "$exp"
    printf 'export REMOTE_DIR=%q\n' "$REMOTE_DIR"
    printf 'export JOB_COMMAND=%q\n' "$JOB_COMMAND"
    printf 'export VENV_PATH=%q\n' "${VENV_PATH:-}"
    printf 'export MODULES=%q\n' "${MODULES:-}"
    printf 'export HF_HOME=%q\n' "${HF_HOME:-}"
    echo ""
    cat "$HERE/job_template.sh"
}

cmd_run() {
    _take_campaign "$@"
    set -- ${REST[@]+"${REST[@]}"}

    local exp="${1:-}"
    if [ -z "$exp" ]; then
        echo "run.sh run: missing <exp>" >&2
        exit 2
    fi
    shift

    local dry_run=0
    local sbatch_args=()
    for arg in ${@+"$@"}; do
        if [ "$arg" = "--dry-run" ]; then dry_run=1; else sbatch_args+=("$arg"); fi
    done

    local campaign script
    campaign="$(_campaign)"
    script="$(render "$exp")"
    _check_syntax "job script" "$script"

    if [ "$dry_run" -eq 1 ]; then
        # Previewed off the same _submit_plan a real submit walks, first rung
        # first: with the ladder active a real sbatch carries --partition and a
        # clamped --time, and a preview without them describes a submission
        # that will not happen.
        local rung wt rungs="" first_rung="" first_args=""
        while IFS=$'\t' read -r rung wt; do
            rungs="${rungs}${rungs:+ }${rung}"
            if [ -z "$first_rung" ]; then
                first_rung="$rung"
                first_args="$(_rung_args "$rung" "$wt")"
            fi
        done <<<"$(_submit_plan)"
        echo "[dry-run] campaign=${campaign} exp=${exp} partition=${first_rung}"
        if [ "$rungs" != "$first_rung" ]; then
            echo "[dry-run] fallback ladder: ${rungs}"
        fi
        echo "[dry-run] would submit: sbatch ${first_args} ${sbatch_args[*]-} _slurm/${exp}.sbatch"
        echo "[dry-run] nothing was written to ${UNITY_HOST}:${REMOTE_DIR}"
        return 0
    fi

    _ssh "$UNITY_HOST" "mkdir -p ${REMOTE_DIR}/_slurm"
    printf '%s\n' "$script" | _ssh "$UNITY_HOST" "cat > ${REMOTE_DIR}/_slurm/${exp}.sbatch"

    if ! _submit_ladder "_slurm/${exp}.sbatch" ${sbatch_args[@]+"${sbatch_args[@]}"}; then
        echo "run.sh:   the job is NOT in the ledger and status/fetch will not see it." >&2
        return 0
    fi
    local job_id="$SUBMIT_JOB_ID"

    if ! _write_provenance "$job_id" "$exp" "$campaign"; then
        echo "run.sh: WARNING job ${job_id} was submitted without provenance" >&2
    fi
    if _ledger record "$campaign" "$job_id" "$exp" "$SUBMIT_PARTITION"; then
        echo "Recorded job ${job_id} in campaign ${campaign} (.unity_state/${campaign}.db)"
    else
        echo "run.sh: WARNING job ${job_id} was submitted but could not be recorded" >&2
        echo "run.sh:   in ${STATE_DIR}/${campaign}.db -- status/fetch will not see it." >&2
    fi
}

render_array() {
    local campaign="$1" limit="${2:-}"
    require SLURM_ACCOUNT
    require REMOTE_DIR
    require JOB_COMMAND
    [ -z "$SLURM_CONSTRAINT" ] || _require_safe_constraint "$SLURM_CONSTRAINT"
    _require_safe_name "campaign name" "$campaign"

    echo "#!/bin/bash"
    echo "#SBATCH --job-name=${campaign}"
    echo "#SBATCH --account=${SLURM_ACCOUNT}"
    echo "#SBATCH --partition=${SLURM_PARTITION}"
    echo "#SBATCH --time=${WALLTIME}"
    echo "#SBATCH --nodes=${SLURM_NODES}"
    echo "#SBATCH --cpus-per-task=${SLURM_CPUS}"
    echo "#SBATCH --mem=${SLURM_MEM}"
    echo "#SBATCH --output=${REMOTE_DIR}/_slurm/${campaign}-%A_%a.out"
    echo "#SBATCH --error=${REMOTE_DIR}/_slurm/${campaign}-%A_%a.err"
    if [ -n "$SLURM_GPUS" ] && [ "$SLURM_GPUS" != "0" ]; then
        if [ -n "$SLURM_GPU_TYPE" ]; then
            echo "#SBATCH --gres=gpu:${SLURM_GPU_TYPE}:${SLURM_GPUS}"
        else
            echo "#SBATCH --gres=gpu:${SLURM_GPUS}"
        fi
    fi
    if [ -n "$SLURM_CONSTRAINT" ]; then
        echo "#SBATCH --constraint=${SLURM_CONSTRAINT}"
    fi
    if [ -n "$limit" ]; then
        echo "#SBATCH --array=0-$((${ARRAY_COUNT} - 1))%${limit}"
    else
        echo "#SBATCH --array=0-$((${ARRAY_COUNT} - 1))"
    fi
    echo "#SBATCH --mail-type=END,FAIL,TIME_LIMIT"
    if [ -n "${USER_EMAIL:-}" ]; then
        echo "#SBATCH --mail-user=${USER_EMAIL}"
    fi
    echo ""
    # Each task reads its own line out of the manifest AT RUNTIME, not at submit
    # time, so the path it reads must belong to THIS array alone. Keyed by
    # campaign name, a second `run.sh array` under the same campaign overwrote
    # the file while this array's tasks were still queued, and they then ran the
    # other array's units under this job id with no error anywhere. The parent
    # job id only exists once sbatch has replied, so the path is spelled with
    # the runtime variable and cmd_array uploads the file immediately after
    # submitting; the wait below covers the seconds in between.
    cat <<'ARRAY_MANIFEST_GUARD'
if [ -z "${SLURM_ARRAY_JOB_ID:-}" ]; then
    echo "run.sh array task: SLURM_ARRAY_JOB_ID is unset -- this script only" >&2
    echo "run.sh array task:   runs as a SLURM array job." >&2
    exit 1
fi
ARRAY_MANIFEST_GUARD
    printf 'export UNITY_MANIFEST=%q"${SLURM_ARRAY_JOB_ID}.manifest"\n' \
        "${REMOTE_DIR}/_slurm/${campaign}-"
    cat <<'ARRAY_MANIFEST_WAIT'
_unity_wait=0
while [ ! -f "$UNITY_MANIFEST" ] && [ "$_unity_wait" -lt 60 ]; do
    sleep 2
    _unity_wait=$((_unity_wait + 1))
done
if [ ! -f "$UNITY_MANIFEST" ]; then
    echo "run.sh array task: ${UNITY_MANIFEST} never appeared -- the submitting" >&2
    echo "run.sh array task:   run.sh could not upload it. Nothing was run." >&2
    exit 1
fi
ARRAY_MANIFEST_WAIT
    # No backslashes in this format string. bash's printf leaves `\$` as a
    # literal backslash-dollar and drops the backslash from `\"`, so an escaped
    # version of this line reaches the cluster as unparseable bash. The nested
    # double quotes are already valid inside `$( )`, and the single-quoted
    # format string is what stops the local shell expanding $(...) here.
    printf 'export EXP="$(sed -n "$((SLURM_ARRAY_TASK_ID + 1))p" "$UNITY_MANIFEST")"\n'
    printf 'export REMOTE_DIR=%q\n' "$REMOTE_DIR"
    printf 'export JOB_COMMAND=%q\n' "$JOB_COMMAND"
    printf 'export VENV_PATH=%q\n' "${VENV_PATH:-}"
    printf 'export MODULES=%q\n' "${MODULES:-}"
    printf 'export HF_HOME=%q\n' "${HF_HOME:-}"
    echo ""
    cat "$HERE/job_template.sh"
}

cmd_array() {
    local manifest="${1:-}"
    if [ -z "$manifest" ] || [ ! -f "$manifest" ]; then
        echo "run.sh array: manifest file is required" >&2
        exit 2
    fi
    shift

    local campaign limit
    campaign="${CAMPAIGN:-}"
    limit=""
    local sbatch_args=()
    while [ $# -gt 0 ]; do
        case "$1" in
            --campaign) campaign="${2:-}"; shift 2 ;;
            --campaign=*) campaign="${1#--campaign=}"; shift ;;
            --limit) limit="${2:-}"; shift 2 ;;
            --limit=*) limit="${1#--limit=}"; shift ;;
            --dry-run) echo "run.sh array: --dry-run is not supported; use render" >&2; exit 2 ;;
            *) sbatch_args+=("$1"); shift ;;
        esac
    done
    [ -n "$campaign" ] || campaign="$(date -u +%Y%m%d)"
    _require_safe_name "campaign name" "$campaign"

    local normalized
    normalized="$(mktemp)"
    trap 'rm -f "$normalized"' RETURN
    while IFS= read -r exp || [ -n "$exp" ]; do
        [ -n "${exp//[[:space:]]/}" ] || continue
        case "$exp" in \#*) continue ;; esac
        _require_safe_name "experiment name" "$exp"
        printf '%s\n' "$exp" >>"$normalized"
    done <"$manifest"
    ARRAY_COUNT="$(wc -l <"$normalized")"
    if [ "$ARRAY_COUNT" -eq 0 ]; then
        echo "run.sh array: manifest has no experiments" >&2
        exit 2
    fi

    local script parent
    script="$(render_array "$campaign" "$limit")"
    _check_syntax "array script" "$script"
    _ssh "$UNITY_HOST" "mkdir -p ${REMOTE_DIR}/_slurm"
    printf '%s\n' "$script" | _ssh "$UNITY_HOST" "cat > ${REMOTE_DIR}/_slurm/${campaign}.array.sbatch"

    if ! _submit_ladder "_slurm/${campaign}.array.sbatch" ${sbatch_args[@]+"${sbatch_args[@]}"}; then
        echo "run.sh:   the manifest is keyed by the job id, so it was NOT uploaded and" >&2
        echo "run.sh:   every task will exit with a missing-manifest error. Check squeue." >&2
        return 0
    fi
    parent="$SUBMIT_JOB_ID"
    # The tasks are queued and reading for this file already; upload it now,
    # under a name no other array can write to.
    if ! _ssh "$UNITY_HOST" \
            "cat > ${REMOTE_DIR}/_slurm/${campaign}-${parent}.manifest" <"$normalized"; then
        echo "run.sh: WARNING array ${parent}'s manifest could not be uploaded --" >&2
        echo "run.sh:   its tasks will exit with a missing-manifest error." >&2
    fi
    if _ledger array "$campaign" "$parent" "$SUBMIT_PARTITION" "$normalized"; then
        echo "Recorded ${ARRAY_COUNT} array tasks under campaign ${campaign}"
    else
        echo "run.sh: WARNING array job ${parent} was submitted but could not be recorded" >&2
    fi
}

cmd_sync() {
    bash "$HERE/sync.sh"
}

cmd_jobs() {
    _take_campaign "$@"
    local campaign rows
    campaign="$(_campaign)"
    rows="$(_ledger rows "$campaign")"
    if [ -z "$rows" ]; then
        echo "No jobs recorded for campaign ${campaign}."
        echo "Submit one with: bash unityHPC/run.sh run <exp>"
        return 0
    fi
    echo "Campaign: ${campaign}"
    printf '%-10s %-20s %-14s %s\n' job_id exp partition status
    printf '%s\n' "$rows" | while IFS=$'\t' read -r id exp part status; do
        printf '%-10s %-20s %-14s %s\n' "$id" "$exp" "$part" "$status"
    done
}

cmd_status() {
    _take_campaign "$@"
    local campaign ids sacct_out changed
    campaign="$(_campaign)"
    ids="$(_ledger ids "$campaign")"
    if [ -z "$ids" ]; then
        echo "No jobs recorded for campaign ${campaign}."
        return 0
    fi
    if ! sacct_out="$(_ssh "$UNITY_HOST" \
            "sacct -j '${ids}' -X -P -n -o JobID,State,Partition,Elapsed" 2>&1)"; then
        echo "run.sh: sacct failed -- showing the last known state instead" >&2
        printf '%s\n' "$sacct_out" | sed 's/^/run.sh:   /' >&2
        cmd_jobs --campaign "$campaign"
        return 0
    fi
    changed="$(_ledger update "$campaign" "$sacct_out")"
    cmd_jobs --campaign "$campaign"
    echo "(${changed:-0} state(s) updated from sacct)"
}

cmd_logs() {
    local lines=40
    local args=()
    while [ $# -gt 0 ]; do
        case "$1" in
            -n) lines="${2:-40}"; shift 2 ;;
            -n*) lines="${1#-n}"; shift ;;
            *) args+=("$1"); shift ;;
        esac
    done
    _take_campaign ${args[@]+"${args[@]}"}
    require REMOTE_DIR

    local campaign newest job_id exp
    campaign="$(_campaign)"
    newest="$(_ledger newest "$campaign")"
    if [ -z "$newest" ]; then
        echo "No jobs recorded for campaign ${campaign}."
        return 0
    fi
    job_id="$(printf '%s' "$newest" | cut -f1)"
    exp="$(printf '%s' "$newest" | cut -f2)"
    local log_name="${exp}-${job_id}"
    if [[ "$job_id" == *_* ]]; then log_name="${campaign}-${job_id}"; fi
    # Both streams, always. Most jobs fail through stderr, and a tool that reads
    # only .out can report that a job failed but never why.
    local stream
    for stream in out err; do
        echo "--- ${log_name}.${stream} (last ${lines} lines) ---"
        _ssh "$UNITY_HOST" "tail -n ${lines} ${REMOTE_DIR}/_slurm/${log_name}.${stream} 2>&1 || true"
    done
}

cmd_fetch() {
    _take_campaign "$@"
    require REMOTE_DIR

    local campaign rows dest
    campaign="$(_campaign)"
    rows="$(_ledger rows "$campaign")"
    dest="$PROJECT_DIR/_results/$campaign"
    mkdir -p "$dest"

    local filters=()
    if [ -n "$rows" ]; then
        while IFS=$'\t' read -r id exp _part _status; do
            [ -n "$id" ] || continue
            local stem="${exp}-${id}"
            if [[ "$id" == *_* ]]; then stem="${campaign}-${id}"; fi
            filters+=("--include=${stem}.out" "--include=${stem}.err")
        done <<<"$rows"
        filters+=("--exclude=*")
    else
        echo "No jobs recorded for campaign ${campaign} -- fetching all of _slurm/."
    fi

    rsync -az ${filters[@]+"${filters[@]}"} \
        "${UNITY_HOST}:${REMOTE_DIR}/_slurm/" "$dest/"

    local remote_results="${REMOTE_RESULTS_DIR:-${REMOTE_DIR}/_results}"
    if _ssh "$UNITY_HOST" "test -d '${remote_results}'"; then
        mkdir -p "$dest/artifacts"
        rsync -az "${UNITY_HOST}:${remote_results}/" "$dest/artifacts/"
        echo "Artifacts: _results/${campaign}/artifacts/"
    fi
    echo "Fetched to _results/${campaign}/"
    ls -1 "$dest" | sed 's/^/  /'
}

# Guarded so a test can `source run.sh` to reach the functions above without
# also running a subcommand: sourcing sets BASH_SOURCE[0] to this file while
# leaving $0 as the caller's shell, which a normal `bash run.sh ...` invocation
# never does.
if [ "${BASH_SOURCE[0]}" = "${0}" ]; then
    case "${1:-}" in
        version|--version)
                echo "unityHPC/run.sh generated by unity-hpc ${UNITY_SCAFFOLD_VERSION}"
                echo "Re-run /unity-hpc:setup (or hpc-scaffold) to regenerate it." ;;
        run)    shift; cmd_run "$@" ;;
        array)  shift; cmd_array "$@" ;;
        render) shift; render "${1:-preview}" ;;
        sync)   cmd_sync ;;
        status) shift; cmd_status "$@" ;;
        jobs)   shift; cmd_jobs "$@" ;;
        logs)   shift; cmd_logs "$@" ;;
        fetch)  shift; cmd_fetch "$@" ;;
        *)      echo "usage: run.sh {run <exp> [--campaign N] [--dry-run] [sbatch args] |" >&2
                echo "                array <manifest> [--campaign N] [--limit N] [sbatch args] |" >&2
                echo "                render <exp> | sync | status | jobs | logs | fetch}" >&2
                exit 2 ;;
    esac
fi
